	count(*) as numcust,
	sum(c_acctbal) as totacctbal
from
	(
		select
			substring(c_phone from 1 for 2) as cntrycode,
			c_acctbal
		from
			customer
		where
			substring(c_phone from 1 for 2) in
				('27', '12', '24', '14', '11', '10', '20')
			and c_acctbal > (
				select
					avg(c_acctbal)
				from
