				where
					c_acctbal > 0.00
					and substring(c_phone from 1 for 2) in
						('27', '12', '24', '14', '11', '10', '20')
			)
			and not exists (
				select
					*
				from
					orders
				where
					o_custkey = c_custkey
			)
	) as custsale
group by
	cntrycode
