				('20', '24', '27', '18', '23', '29', '32')
			and c_acctbal > (
				select
					avg(c_acctbal)
				from
					customer
				where
					c_acctbal > 0.00
					and substring(c_phone from 1 for 2) in
						('20', '24', '27', '18', '23', '29', '32')
			)
			and not exists (
				select
