	count(*) as numcust,
	sum(c_acctbal) as totacctbal
from
	(
		select
			substring(c_phone from 1 for 2) as cntrycode,
			c_acctbal
		from
			customer
		where
			substring(c_phone from 1 for 2) in
				('28', '31', '23', '10', '19', '21', '24')
			and c_acctbal > (
				select
					avg(c_acctbal)
				from
