				where
					c_acctbal > 0.00
					and substring(c_phone from 1 for 2) in
						('17', '32', '31', '24', '11', '12', '20')
			)
			and not exists (
				select
					*
				from
					orders
				where
					o_custkey = c_custkey
			)
	) as custsale
group by
	cntrycode
order by
	cntrycode;
